def variant_offset(trades, o0):
    last_stop = {}  # sym -> (t1, exit_price)
    keep, dropped = [], 0
    for t in trades:
        sym = t["sym"]
        prev = last_stop.get(sym)
        allowed = True
        if prev is not None:
            dt_h = (t["t0"] - prev[0]) / MS_H
            o = o0 * (0.5 ** (dt_h / 2.0))
            level = prev[1] * (1 - o / 1e4)
            if t["entry"] > level:
                allowed = False
        if not allowed:
            dropped += 1
            continue
        keep.append(t)
        if t["reason"] == "stop":
            last_stop[sym] = (t["t1"], exit_price(t))
        else:
            last_stop.pop(sym, None)
    return keep, dropped

